import { useCallback, useEffect, useState } from 'react';
import { paperAPI } from '../utils/api';
import { useAuth } from '../context/AuthContext';

const STORAGE_PREFIX = 'pts:lastSeenPaperAt:';
const POLL_INTERVAL = 15000;

export default function usePaperNotifications() {
  const { user } = useAuth();
  const storageKey = user?.id ? `${STORAGE_PREFIX}${user.id}` : '';
  const [lastSeenAt, setLastSeenAt] = useState(null);
  const [notifCount, setNotifCount] = useState(0);

  useEffect(() => {
    if (!storageKey || typeof window === 'undefined') {
      setLastSeenAt(null);
      setNotifCount(0);
      return;
    }

    const storedValue = window.localStorage.getItem(storageKey);
    if (storedValue) {
      const parsed = Number(storedValue);
      setLastSeenAt(Number.isFinite(parsed) ? parsed : Date.now());
      return;
    }

    const now = Date.now();
    window.localStorage.setItem(storageKey, String(now));
    setLastSeenAt(now);
    setNotifCount(0);
  }, [storageKey]);

  const refreshNotifications = useCallback(async () => {
    if (!storageKey || lastSeenAt == null) return;

    try {
      const r = await paperAPI.list();
      const papers = r.data.papers || [];
      const unseenCount = papers.filter(paper => {
        const createdAt = new Date(paper.created_at).getTime();
        return Number.isFinite(createdAt) && createdAt > lastSeenAt;
      }).length;
      setNotifCount(unseenCount);
    } catch {
      // Keep the previous badge count if the refresh fails.
    }
  }, [lastSeenAt, storageKey]);

  useEffect(() => {
    if (lastSeenAt == null) return;

    refreshNotifications();
    const timer = window.setInterval(refreshNotifications, POLL_INTERVAL);
    return () => window.clearInterval(timer);
  }, [lastSeenAt, refreshNotifications]);

  const markNotificationsSeen = useCallback(() => {
    if (!storageKey || typeof window === 'undefined') return;

    const now = Date.now();
    window.localStorage.setItem(storageKey, String(now));
    setLastSeenAt(now);
    setNotifCount(0);
  }, [storageKey]);

  return { notifCount, refreshNotifications, markNotificationsSeen };
}
